'use strict';

const fs = require('fs');
const input = fs.readFileSync(0, 'utf8').trim().split(/\s+/);

const P = Number(input[0]);
const output = [];
const LIMIT = 5_000_000n;

let index = 1;

for (let q = 0; q < P; q++) {
  const L = BigInt(input[index++]);
  const A = BigInt(input[index++]);
  const B = BigInt(input[index++]);

  const count = B - A + 1n;
  const cap = count < LIMIT ? count : LIMIT;

  let low = 0n;
  let high = cap + 1n;

  while (low + 1n < high) {
    const mid = (low + high) / 2n;
    const sum = mid * (2n * A + mid - 1n) / 2n;

    if (sum < L) low = mid;
    else high = mid;
  }

  const rounds = low + 1n < count ? low + 1n : count;
  output.push(rounds.toString());
}

process.stdout.write(output.join('\n'));
